import { useContext } from '@soybeanjs/headless/composables';
import type { ChartContext } from './types';

/**
 * Chart context bridge.
 *
 * `SChartContainer` provides `{ id, config }`; `SChartLegendContent` and
 * `SChartStyle` consume it to resolve colors and scoped selectors.
 */
export const [provideChartContext, useChartContext] = useContext<ChartContext>('Chart');

import type { Component, Ref } from 'vue';

/**
 * Chart color theme contexts.
 *
 * `''` matches the root selector (light), `.dark` matches the dark root.
 * Mirrors the theme engine's `darkSelector` contract used by `@soybeanjs/ui`.
 */
export const chartThemes = { light: '', dark: '.dark' } as const;

export type ChartThemeKey = keyof typeof chartThemes;

/**
 * The theme's chart palette, ready for `ChartConfig` `color` values.
 *
 * The theme engine stores `--chart-N` as raw HSL channel triplets
 * (`--chart-1: 20.5 90.2% 48.2%`), so each reference is wrapped in `hsl()`
 * to be a valid CSS color. Use these instead of writing `var(--chart-N)`.
 */
export const chartColors = [
  'hsl(var(--chart-1))',
  'hsl(var(--chart-2))',
  'hsl(var(--chart-3))',
  'hsl(var(--chart-4))',
  'hsl(var(--chart-5))'
] as const;

/**
 * Declarative configuration for a chart's data series.
 *
 * Each key maps a series/`dataKey` to its label, optional icon and color.
 * Color can be a single CSS color or a per-theme map resolved at render time.
 */
export type ChartConfig = {
  [k in string]: {
    label?: string | Component;
    icon?: string | Component;
  } & ({ color?: string; theme?: never } | { color?: never; theme: Record<ChartThemeKey, string> });
};

/** Reactive context shared between `SChartContainer` and its chart parts. */
export interface ChartContext {
  /** Sanitized chart id bound to `data-chart`, used by legend/style selectors. */
  id: string;
  /** Reactive chart config consumed by tooltip/legend/style parts. */
  config: Ref<ChartConfig>;
}

import { h, render } from 'vue';
import type { Component } from 'vue';
import type { ChartConfig } from '../types';

/**
 * Module-level render cache keyed by the serialized data payload.
 *
 * Bounded by the number of distinct hovered datum per chart; avoids re-rendering
 * a tooltip/legend Vue component to an HTML string on every pointer move.
 */
const cache = new Map<string, string>();

let counter = 0;

/** Stable string key for a data payload, order-independent for top-level keys. */
function serializeKey(key: Record<string, unknown>): string {
  return JSON.stringify(key, Object.keys(key).sort());
}

/**
 * Render a Vue component to an HTML string for chart-library `template` props.
 *
 * Unovis tooltips/crosshairs accept a string template; this renders
 * `SChartTooltipContent` (with `payload`/`config`/`x`) into the DOM once per
 * datum and caches the result. Returns `undefined` on the server.
 */
export function componentToString(config: ChartConfig, component: Component, props?: object) {
  if (typeof document === 'undefined') {
    return undefined;
  }

  const id = `chart-cache-${++counter}`;

  return (_data: unknown, x: number | Date) => {
    const data = 'data' in (_data as Record<string, unknown>) ? (_data as { data: unknown }).data : _data;
    const serializedKey = `${id}-${serializeKey(data as Record<string, unknown>)}`;
    const cachedContent = cache.get(serializedKey);
    if (cachedContent) {
      return cachedContent;
    }

    const vnode = h(component, { ...props, payload: data, config, x });
    const div = document.createElement('div');
    render(vnode, div);
    const content = div.innerHTML;
    cache.set(serializedKey, content);
    return content;
  };
}

import { chartThemes } from '../types';
import type { ChartConfig, ChartThemeKey } from '../types';

/**
 * Build the scoped CSS that maps each config key to a `--color-{key}` variable.
 *
 * The output is scoped to `[data-chart={id}]` per theme selector (`''` for
 * light, `.dark` for dark), letting chart library parts reference
 * `var(--color-{key})` for series colors. Pure and SSR-safe.
 */
export function buildChartColorCss(id: string, config: ChartConfig): string {
  const colorConfig = Object.entries(config).filter(([, item]) => item.theme || item.color);
  if (colorConfig.length === 0) {
    return '';
  }

  return (Object.keys(chartThemes) as ChartThemeKey[])
    .map(theme => {
      const prefix = chartThemes[theme];
      const cssVars = colorConfig
        .map(([key, item]) => {
          const color = item.theme?.[theme] ?? item.color;
          return color ? `  --color-${key}: ${color};` : null;
        })
        .filter((line): line is string => Boolean(line))
        .join('\n');

      return `${prefix} [data-chart=${id}] {\n${cssVars}\n}`;
    })
    .join('\n');
}

// @unocss-include
import { scv } from '@soybeanjs/cva';

/**
 * Chart tooltip content recipe.
 *
 * Indicator variants drive both the row alignment and the indicator size/shape;
 * `nestLabel` switches the value column to end-alignment when a single nested
 * series is rendered.
 */
export const chartTooltipContentVariants = scv({
  slots: {
    root: 'grid min-w-[8rem] items-start gap-1.5 rounded-lg border border-border/50 bg-background px-2.5 py-1.5 text-xs shadow-xl',
    label: 'font-medium',
    items: 'grid gap-1.5',
    item: 'flex w-full flex-wrap items-stretch gap-2 [&>svg]:h-2.5 [&>svg]:w-2.5 [&>svg]:text-muted-foreground',
    indicator: 'shrink-0 rounded-xs border-[var(--color-border)] bg-[var(--color-bg)]',
    itemContent: 'flex flex-1 justify-between leading-none',
    itemLabelWrap: 'grid gap-1.5',
    itemTitle: 'font-medium',
    itemLabel: 'text-muted-foreground',
    itemValue: 'font-mono font-medium tabular-nums text-foreground'
  },
  variants: {
    indicator: {
      dot: {
        item: 'items-center',
        indicator: 'h-2.5 w-2.5'
      },
      line: {
        indicator: 'w-1'
      },
      dashed: {
        indicator: 'w-0 border-[1.5px] border-dashed bg-transparent'
      }
    },
    nestLabel: {
      true: {
        item: 'items-end',
        indicator: 'my-0.5'
      },
      false: {
        item: 'items-center'
      }
    }
  },
  defaultVariants: {
    indicator: 'dot',
    nestLabel: false
  }
});

// @unocss-include
import { scv } from '@soybeanjs/cva';

/**
 * Chart legend content recipe.
 *
 * `verticalAlign` controls top/bottom padding relative to the chart area.
 */
export const chartLegendContentVariants = scv({
  slots: {
    root: 'flex items-center justify-center gap-4',
    item: 'flex items-center gap-1.5 [&>svg]:h-3 [&>svg]:w-3 [&>svg]:text-muted-foreground',
    indicator: 'h-2 w-2 shrink-0 rounded-xs',
    label: ''
  },
  variants: {
    verticalAlign: {
      top: {
        root: 'pb-3'
      },
      bottom: {
        root: 'pt-3'
      }
    }
  },
  defaultVariants: {
    verticalAlign: 'bottom'
  }
});

import type { HTMLAttributes } from 'vue';
import type { ClassValue } from '@soybeanjs/headless/types';
import type { ChartConfig } from '../../types';

/**
 * Properties for the SChartContainer component.
 */
export interface ChartContainerProps extends /** @vue-ignore */ HTMLAttributes {
  /**
   * Declarative chart configuration.
   */
  config: ChartConfig;
  /**
   * Whether to render a crosshair cursor on hover.
   * @default true
   */
  cursor?: boolean;
  /**
   * Additional class names applied to the root element.
   */
  class?: ClassValue;
}

/**
 * Slot bindings for the SChartContainer component.
 */
export type ChartContainerSlots = {
  default: (props: {
    /** Sanitized chart id bound to `data-chart`. */
    id: string;
    /** Chart config provided to chart parts. */
    config: ChartConfig;
  }) => any;
};

import type { HTMLAttributes } from 'vue';
import type { ClassValue } from '@soybeanjs/headless/types';
import type { ChartConfig } from '../../types';

/**
 * Properties for the SChartTooltipContent component.
 */
export interface ChartTooltipContentProps extends /** @vue-ignore */ HTMLAttributes {
  /**
   * Whether to hide the tooltip label.
   */
  hideLabel?: boolean;
  /**
   * Whether to hide the series indicator.
   */
  hideIndicator?: boolean;
  /**
   * Indicator style.
   * @default 'dot'
   */
  indicator?: 'line' | 'dot' | 'dashed';
  /**
   * Key used to resolve the tooltip label from the config.
   */
  labelKey?: string;
  /**
   * Custom formatter for the tooltip label.
   */
  labelFormatter?: (d: number | Date) => string;
  /**
   * Payload entry provided by the chart library.
   */
  payload?: Record<string, unknown>;
  /**
   * Chart config used to resolve series metadata.
   */
  config?: ChartConfig;
  /**
   * X value of the hovered datum.
   */
  x?: number | Date;
  /**
   * Additional class names applied to the root element.
   */
  class?: ClassValue;
}

import type { HTMLAttributes } from 'vue';
import type { ClassValue } from '@soybeanjs/headless/types';

/**
 * Properties for the SChartLegendContent component.
 */
export interface ChartLegendContentProps extends /** @vue-ignore */ HTMLAttributes {
  /**
   * Whether to hide the series icon.
   */
  hideIcon?: boolean;
  /**
   * Key of the series name within each config entry.
   */
  nameKey?: string;
  /**
   * Legend placement relative to the chart area.
   * @default 'bottom'
   */
  verticalAlign?: 'bottom' | 'top';
  /**
   * Additional class names applied to the root element.
   */
  class?: ClassValue;
}

/**
 * Properties for the SChartStyle component.
 *
 * Internal helper rendered by `SChartContainer`; it injects the scoped
 * `--color-{key}` CSS variables for a single chart via a `<style>` element.
 */
export interface ChartStyleProps {
  /**
   * Chart id used to scope the generated CSS selectors.
   */
  id?: string;
}
